private fun icon(name: String, vararg paths: String): ImageVector = build(name, autoMirror = false, paths)

/** A directional icon (an arrow) that flips in right-to-left layouts, like Material's AutoMirrored set. */
private fun mirroredIcon(name: String, vararg paths: String): ImageVector = build(name, autoMirror = true, paths)

private fun build(name: String, autoMirror: Boolean, paths: Array<out String>): ImageVector =
    ImageVector.Builder(
        name = name,
        defaultWidth = 24.dp,
        defaultHeight = 24.dp,
        viewportWidth = 24f,
        viewportHeight = 24f,
        autoMirror = autoMirror,
    ).apply {
        paths.forEach { addPath(pathData = addPathNodes(it), fill = SolidColor(Color.Black)) }
    }.build()
